target.css:
:root {
  --ink: #17352d;
  --muted: #667a70;
  --paper: #fffef9;
  --line: #d8e2da;
  --leaf: #317454;
  --leaf-pale: #e5f1e8;
  --sun: #e8aa3d;
  --sun-pale: #fff2d9;
}

.canopy-card {
  width: 500px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 16px;
  display: grid;
  gap: 12px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.heading-group p,
.tree-profile p,
.metric span,
.metric small,
.crew p {
  margin: 0;
}

.eyebrow {
  color: var(--leaf);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.09em;
}

h1 {
  margin: 3px 0 0;
  font-size: 22px;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.status-badge {
  background: var(--leaf-pale);
  color: var(--leaf);
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 800;
}

.workspace {
  display: grid;
  grid-template-columns: 1.08fr 1fr;
  gap: 12px;
}

.tree-profile {
  background: var(--leaf-pale);
  border-radius: 13px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.tree-topline {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tree-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  background: var(--paper);
  border-radius: 10px;
  font-size: 20px;
}

.tree-type {
  font-size: 14px;
  font-weight: 800;
  line-height: 1.1;
}

.tree-id {
  margin-top: 3px !important;
  color: var(--muted);
  font-size: 11px;
}

.plot {
  margin: 10px 0 0;
  padding-top: 9px;
  border-top: 1px solid var(--line);
  display: flex;
  align-items: center;
  gap: 8px;
}

.plot-dot {
  width: 9px;
  height: 9px;
  border: 3px solid var(--paper);
  border-radius: 50%;
  background: var(--leaf);
}

figcaption {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

figcaption strong {
  color: var(--ink);
  font-size: 11px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.metric {
  border: 1px solid var(--line);
  border-radius: 11px;
  padding: 9px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.metric span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.metric strong {
  margin-top: 4px;
  font-size: 17px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.metric small {
  margin-top: 4px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.15;
}

.accent-metric {
  border-color: var(--leaf);
}

.accent-metric strong {
  color: var(--leaf);
}

.warning-metric {
  background: var(--sun-pale);
  border-color: var(--sun);
}

.warning-metric strong {
  color: var(--sun);
  font-size: 14px;
}

.card-footer {
  border-top: 1px solid var(--line);
  padding-top: 10px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.crew {
  display: flex;
  align-items: center;
  gap: 8px;
}

.avatars {
  display: flex;
}

.avatars span {
  width: 25px;
  height: 25px;
  display: grid;
  place-items: center;
  border: 2px solid var(--paper);
  border-radius: 50%;
  background: var(--leaf);
  color: var(--paper);
  font-size: 8px;
  font-weight: 800;
}

.avatars span + span {
  margin-left: -7px;
  background: var(--sun);
}

.crew p {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.25;
}

.crew strong {
  color: var(--ink);
  font-size: 11px;
}

button {
  border: 0;
  border-radius: 9px;
  padding: 8px 10px;
  background: var(--ink);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

button span {
  margin-left: 5px;
  color: var(--sun);
  font-size: 14px;
}

